<script setup>
import { quotationSelection } from "./quantity.js";
import {printDocument} from "./printing.js";
import {ref, computed, onBeforeUnmount} from 'vue';
import {showSectionGenerator} from './section-generator.js';
import ChantierAutocomplete from './ChantierAutocomplete.vue';
import FrappeCell from './FrappeCell.vue';
import { assignmentIds } from './chantier-selection.js';
import CommercialExtrasPanel from './CommercialExtrasPanel.vue';
const frappe = window.frappe;
const api='mat_reco.material_reconfiguration.services.chantier_service.';
const data=ref({chantiers:[],sections:[],quotations:[],lines:[],summary:{}}), selected=ref(''), section=ref(''), busy=ref(false), error=ref('');
const dirty=ref(false), chosen=ref({}), quoteKey=ref(null),assignmentTargets=ref([]),expandedArticles=ref({});
const sectionsOpen=ref(true),drawerTargets=ref([]);
const sectionTarget=ref('');
const sectionRow=computed(()=>(data.value.chantier?.lines||[]).find(row=>row.line_id===sectionTarget.value));
function pickSection(row){sectionTarget.value=sectionTarget.value===row.line_id?'':row.line_id;sectionsOpen.value=true;}
function assignSection(value){if(!commercialDraft.value||busy.value||!sectionRow.value||!(value===''||data.value.sections.some(s=>s.name===value)))return;sectionRow.value.section=value;dirty.value=true;}
function openExtras(row){sectionTarget.value='';drawerTargets.value=assignmentIds(assignmentTargets.value,row.line_id);}
const total=computed(()=>(data.value.chantier?.lines||[]).reduce((n,r)=>n+Number(r.qty||0)*Number(r.rate||0),0)+(data.value.chantier?.commercial_extras||[]).reduce((n,r)=>n+Number(r.qty||0)*Number(r.rate||0),0));
function toggleAllTargets(){const visible=macroLines.value.map(l=>l.line_id);assignmentTargets.value=visible.every(id=>assignmentTargets.value.includes(id))?assignmentTargets.value.filter(id=>!visible.includes(id)):[...new Set([...assignmentTargets.value,...visible])];}
function applyExtras(rows){if(!rows.length)return;data.value.chantier.commercial_extras||=[];data.value.chantier.commercial_extras.push(...rows);dirty.value=true;}
async function beforeBatch(){return !dirty.value||await saveMacro();}
const technicalApi='mat_reco.material_reconfiguration.services.technical_study_service.';
let serial=0, timer=null;
async function call(method,args={}) { return (await frappe.call({method:api+method,args,type:method==='get_dossier'?'GET':'POST'})).message; }
function describe(e) { try{return JSON.parse(JSON.parse(e._server_messages)[0]).message;}catch{return e.message||'Impossible de charger le dossier.';} }
async function refresh() {
 const request=++serial; busy.value=true;error.value='';
 try {const result=await call('get_dossier',{chantier:selected.value||null});if(request===serial){data.value=result;dirty.value=false;chosen.value=quotationSelection(result.chantier?.lines||[],result.quote_usage);}}
 catch(e){if(request===serial)error.value=describe(e);} finally{if(request===serial)busy.value=false;}
}
function choose(){sectionTarget.value='';section.value='';assignmentTargets.value=[];drawerTargets.value=[];refresh();}
const scope=computed(()=>{const names=new Set(section.value?[section.value]:[]);let changed=true;while(changed){changed=false;for(const s of data.value.sections)if(names.has(s.parent_chantier_section)&&!names.has(s.name)){names.add(s.name);changed=true;}}return names;});
const macroLines=computed(()=>(data.value.chantier?.lines||[]).filter(l=>!section.value||scope.value.has(l.section)));
const commercialDraft=computed(()=>data.value.chantier?.docstatus===0&&data.value.chantier?.status!=='Cancelled'&&data.value.permissions?.write);
const readyForQuote=computed(()=>data.value.chantier?.docstatus===1&&data.value.technical?.docstatus===1&&!data.value.technical_stale);
const techLine=(id)=>data.value.technical?.lines?.find(l=>l.line_id===id);
const effectiveUom=(row)=>row.uom||JSON.parse(techLine(row.line_id)?.tree_json||'{}').stock_uom||'Unité à définir';
const lines=computed(()=>data.value.lines.filter(l=>!section.value||scope.value.has(l.section)));
const summary=computed(()=>section.value?(data.value.by_section?.[section.value]||{}):data.value.summary);
const depth=(node)=>{let n=0,seen=new Set();while(node?.parent_chantier_section&&!seen.has(node.name)){seen.add(node.name);n++;node=data.value.sections.find(s=>s.name===node.parent_chantier_section);}return n;};
const stateName=(value)=>({completed:'Terminée',ready:'Réalisable',partial:'Partiellement réalisable',blocked:'Bloquée',ok:'Besoin satisfait',Preparation:'Préparation',Quotation:'Chiffrage',Confirmed:'Confirmé','In Production':'En fabrication',Completed:'Terminé','On Hold':'Suspendu',Cancelled:'Annulé'})[value]||value;
const sectionName=(name)=>data.value.sections.find(s=>s.name===name)?.section_name||'Sans section';
const fmt=(n)=>Number(n||0).toLocaleString('fr-FR',{maximumFractionDigits:2});
function open(dt,name){frappe.set_route('Form',dt,name);}
function form(title,fields,onSave) {const dialog=new frappe.ui.Dialog({title,fields,primary_action_label:'Enregistrer',async primary_action(values){dialog.disable_primary_action();try{await onSave(values);dialog.hide();await refresh();}catch(e){frappe.msgprint(describe(e));}finally{dialog.enable_primary_action();}}});dialog.show();}
function newChantier(){form('Nouveau chantier',[
 {fieldname:'reference',label:'Référence',fieldtype:'Data',read_only:1,description:'Numéro automatique attribué à l’enregistrement (YYCHANTMM#####).'},{fieldname:'designation',label:'Désignation',fieldtype:'Data',reqd:1},
 {fieldname:'company',label:'Société',fieldtype:'Link',options:'Company',reqd:1,default:frappe.defaults.get_user_default('Company')},
 {fieldname:'customer',label:'Client',fieldtype:'Link',options:'Customer',reqd:1},{fieldname:'responsible',label:'Responsable',fieldtype:'Link',options:'User',default:frappe.session.user},
 {fieldname:'expected_start_date',label:'Début prévu',fieldtype:'Date'},{fieldname:'expected_end_date',label:'Fin de fabrication prévue',fieldtype:'Date'}
 ],async(values)=>{const result=await frappe.call({method:'frappe.client.insert',args:{doc:{doctype:'Chantier',...values}}});selected.value=result.message.name;section.value='';});}
const templateApi='mat_reco.material_reconfiguration.services.chantier_templates.';
function saveSectionTemplate(){form('Enregistrer les sections comme modèle',[
 {fieldname:'template_name',label:'Nom du modèle',fieldtype:'Data',reqd:1}
 ],async(values)=>{const result=await frappe.call({method:templateApi+'save_template',args:{chantier:selected.value,...values}});frappe.show_alert({message:'Modèle enregistré : '+result.message,indicator:'green'});});}
function importSections(){form('Récupérer une arborescence de sections',[
 {fieldname:'source_type',label:'Source',fieldtype:'Select',options:'Modèle\nAutre chantier',default:'Modèle',reqd:1},
 {fieldname:'template',label:'Modèle',fieldtype:'Link',options:'Chantier Section Template',depends_on:'eval:doc.source_type === "Modèle"',mandatory_depends_on:'eval:doc.source_type === "Modèle"'},
 {fieldname:'source_chantier',label:'Chantier source',fieldtype:'Link',options:'Chantier',depends_on:'eval:doc.source_type === "Autre chantier"',mandatory_depends_on:'eval:doc.source_type === "Autre chantier"',get_query:()=>({filters:{name:['!=',selected.value]}})},
 {fieldtype:'HTML',fieldname:'explanation',options:'<p>Les sections et sous-sections seront ajoutées au chantier, dans leur ordre d’origine. Les sections existantes sont conservées. Aucun ouvrage ne sera copié.</p>'}
 ],async(values)=>{const result=await frappe.call({method:templateApi+'apply_sections',args:{chantier:selected.value,...(values.source_type==='Modèle'?{template:values.template}:{source_chantier:values.source_chantier})}});section.value='';frappe.show_alert({message:result.message.count+' section(s) ajoutée(s)',indicator:'green'});});}
function generateSections(){showSectionGenerator(selected.value,async()=>{section.value='';await refresh();},describe);}
function newSection(){form('Nouvelle section',[
 {fieldname:'section_name',label:'Désignation',fieldtype:'Data',reqd:1},
 {fieldname:'parent_chantier_section',label:'Section parente (facultatif)',fieldtype:'Link',options:'Chantier Section',default:section.value||undefined,get_query:()=>({filters:{chantier:selected.value,is_group:1}})}
 ],async(values)=>{await frappe.call({method:'frappe.client.insert',args:{doc:{doctype:'Chantier Section',chantier:selected.value,is_group:1,...values}}});});}
async function tcall(method,args={},write=true){return(await frappe.call({method:technicalApi+method,args,type:write?'POST':'GET'})).message;}
async function saveMacro(){if(busy.value)return false;busy.value=true;error.value='';try{await tcall('save_commercial',{chantier:selected.value,modified:data.value.chantier.modified,lines:JSON.stringify(data.value.chantier.lines),commercial_extras:JSON.stringify(data.value.chantier.commercial_extras||[]),currency:data.value.chantier.currency,selling_price_list:data.value.chantier.selling_price_list,terms:data.value.chantier.terms,header:JSON.stringify(Object.fromEntries(['customer','designation','responsible','expected_start_date','expected_end_date'].map(k=>[k,data.value.chantier[k]])))});await refresh();return true;}catch(e){error.value=describe(e);return false;}finally{busy.value=false;}}
function nextRepere(){const used=new Set(data.value.chantier.lines.map(l=>l.repere));let n=1;while(used.has('OUV-'+String(n).padStart(3,'0')))n++;return 'OUV-'+String(n).padStart(3,'0');}
function editMacro(row=null){
 const line={...(row||{}),repere:nextRepere(),line_id:globalThis.crypto?.randomUUID?.()||'line-'+Date.now()+'-'+Math.random().toString(16).slice(2),designation:row?.designation||'',section:row?.section||section.value,qty:row?.qty||1,uom:row?.uom||'PC',rate:row?.rate||0,rate_set:row?.rate_set||0};
 delete line.name;data.value.chantier.lines.push(line);dirty.value=true;
}
function preventLeave(e){if(dirty.value){e.preventDefault();e.returnValue='';}}
window.addEventListener('beforeunload',preventLeave);
onBeforeUnmount(()=>window.removeEventListener('beforeunload',preventLeave));
const extrasFor=(id)=>(data.value.chantier.commercial_extras||[]).filter(e=>e.parent_line_id===id);
function removeExtra(extra){frappe.confirm('Retirer ce service ou accessoire ?',()=>{data.value.chantier.commercial_extras=data.value.chantier.commercial_extras.filter(e=>e.line_id!==extra.line_id);dirty.value=true;});}
function removeMacro(row){frappe.confirm('Retirer cet ouvrage du brouillon commercial ?',()=>{assignmentTargets.value=assignmentTargets.value.filter(id=>id!==row.line_id);drawerTargets.value=drawerTargets.value.filter(id=>id!==row.line_id);data.value.chantier.lines=data.value.chantier.lines.filter(l=>l.line_id!==row.line_id);data.value.chantier.commercial_extras=(data.value.chantier.commercial_extras||[]).filter(e=>e.parent_line_id!==row.line_id);dirty.value=true;});}
async function technical(){if(dirty.value&&!(await saveMacro()))return;busy.value=true;error.value='';try{const name=await tcall('prepare_study',{chantier:selected.value});frappe.set_route('technical-study',name);}catch(e){error.value=describe(e);}finally{busy.value=false;}}
function viewTechnical(){frappe.set_route('technical-study',data.value.technical.name);}
function submitCommercial(){frappe.confirm('Valider les quantités, prix et conditions commerciales après l’étude technique ?',async()=>{if(dirty.value&&!(await saveMacro()))return;busy.value=true;error.value='';try{await frappe.call({method:'frappe.client.submit',args:{doc:data.value.chantier}});await refresh();}catch(e){error.value=describe(e);}finally{busy.value=false;}});}
function cancelChantier(){frappe.confirm('Annuler ce chantier ? Toutes les études et tous les devis doivent être supprimés ou annulés.',async()=>{busy.value=true;error.value='';try{await tcall('cancel_dossier',{chantier:selected.value,modified:data.value.chantier.modified});await refresh();}catch(e){error.value=describe(e);}finally{busy.value=false;}});}
async function newQuotation(){const selection=Object.entries(chosen.value).filter(([id,v])=>v.selected&&v.qty>0).map(([line_id,v])=>({line_id,qty:v.qty}));if(!selection.length){frappe.msgprint('Sélectionner au moins un ouvrage et sa quantité.');return;}const dialog=new frappe.ui.Dialog({title:'Générer le devis depuis le chantier approuvé',fields:[{fieldname:'submit',label:'Valider également le devis',fieldtype:'Check',default:1}],primary_action_label:'Générer',async primary_action(v){dialog.disable_primary_action();busy.value=true;error.value='';try{quoteKey.value||=globalThis.crypto?.randomUUID?.()||String(Date.now())+Math.random();const name=await tcall('generate_quotation',{chantier:selected.value,selections:JSON.stringify(selection),request_key:quoteKey.value,submit:v.submit});quoteKey.value=null;dialog.hide();await refresh();open('Quotation',name);}catch(e){error.value=describe(e);}finally{dialog.enable_primary_action();busy.value=false;}}});dialog.show();}
function confirmOrder(quote){const dialog=new frappe.ui.Dialog({title:'Confirmer l’acceptation client',fields:[{fieldname:'acceptance',label:'Référence ou justificatif de l’accord client',fieldtype:'Data',reqd:1},{fieldname:'delivery_date',label:'Date prévue',fieldtype:'Date',reqd:1,default:frappe.datetime.add_days(frappe.datetime.get_today(),7)}],primary_action_label:'Créer et valider la commande',async primary_action(v){dialog.disable_primary_action();try{quoteKey.value||=globalThis.crypto?.randomUUID?.()||String(Date.now())+Math.random();const name=await tcall('confirm_order',{quotation:quote.name,acceptance_reference:v.acceptance,delivery_date:v.delivery_date,request_key:quoteKey.value});quoteKey.value=null;dialog.hide();open('Sales Order',name);}catch(e){frappe.msgprint(describe(e));}finally{dialog.enable_primary_action();}}});dialog.show();}
async function mpp(line){busy.value=true;error.value='';try{const name=await call('create_mpp',{sales_order:line.sales_order,sales_order_item:line.sales_order_item});open('Material Production Plan',name);}catch(e){error.value=describe(e);}finally{busy.value=false;}}
function workshop(){sessionStorage.setItem('univers-workshop-chantier',selected.value);frappe.set_route('workshop-cockpit');}
function show(){document.body.classList.add('ug-chantier-active');const stored=sessionStorage.getItem("univers-chantier-selected");if(stored){selected.value=stored;section.value="";sessionStorage.removeItem("univers-chantier-selected");}refresh();clearInterval(timer);timer=setInterval(()=>{if(!busy.value&&!dirty.value)refresh();},60000);}
function hide(){document.body.classList.remove('ug-chantier-active');serial++;clearInterval(timer);timer=null;}
onBeforeUnmount(hide);defineExpose({show,hide});
</script>

<template>
<div class="ug-chantiers" :class="{'drawer-open':commercialDraft&&drawerTargets.length}">
 <div class="chantier-content">
 <header><div><p>UNIVERS GLASS › Chantier › {{selected}}</p><h1>Chantier <small>{{data.chantier?.docstatus===0?'Brouillon commercial':stateName(data.chantier?.status)}}</small></h1></div><div class="actions"><button :disabled="busy||!data.permissions?.chantier" @click="newChantier">+ Nouveau</button><button v-if="commercialDraft" :disabled="busy||!dirty" @click="frappe.confirm('Abandonner les modifications ?',refresh)">Annuler</button><button v-if="commercialDraft" class="primary" :disabled="busy||!dirty" @click="saveMacro">{{busy?'Enregistrement…':'▣ Enregistrer'}}</button><details><summary aria-label="Autres actions">•••</summary><div class="more-actions">
 <button :disabled="busy||dirty" @click="refresh">Actualiser</button><button v-if="commercialDraft" :disabled="dirty||busy" @click="frappe.new_doc('Data Import',{reference_doctype:'Chantier',import_type:'Update Existing Records'})">Importer Excel</button><button v-if="selected" @click="open('Chantier',selected)">Ouvrir le dossier Frappe</button><button :disabled="dirty||!selected" @click="printDocument('Chantier',selected)">Imprimer A4</button><button v-if="data.technical" @click="viewTechnical">Étude technique</button><button v-if="commercialDraft" :disabled="busy||!data.permissions?.technical" @click="technical">Préparer l’étude technique</button><button v-if="commercialDraft&&data.permissions?.submit" :disabled="busy||data.technical?.docstatus!==1||data.technical_stale" @click="submitCommercial">Valider le commercial</button><button :disabled="busy||!data.permissions?.quotation||!readyForQuote" @click="newQuotation">Générer un devis</button><button v-if="selected&&data.permissions?.cancel" :disabled="busy||dirty" @click="cancelChantier">Annuler le chantier</button><button @click="workshop">Atelier</button><button v-for="q in data.quotations" :key="q.name" @click="open('Quotation',q.name)">{{q.name}} · {{q.status}}</button><button v-for="q in data.quotations.filter(q=>q.docstatus===1)" :key="q.name+'order'" @click="confirmOrder(q)">Commander {{q.name}}</button>
 </div></details></div></header>
 <ChantierAutocomplete v-model="selected" :items="data.chantiers" :disabled="busy||dirty" @change="choose" />
 <div v-if="error" class="alert" role="alert">{{error}}</div>
 <p v-if="dirty" role="status">Modifications non enregistrées</p>
 <template v-if="data.chantier?.name===selected">
 <div class="header-fields" @change="dirty=true">
 <section><label>Client <FrappeCell v-model="data.chantier.customer" doctype="Customer" :disabled="!commercialDraft||busy" /></label><label>Nom du chantier <input v-model="data.chantier.designation" :disabled="!commercialDraft||busy" @input="dirty=true" /></label><label>Responsable <FrappeCell v-model="data.chantier.responsible" doctype="User" :disabled="!commercialDraft||busy" /></label></section>
 <section><label>Devise <FrappeCell v-model="data.chantier.currency" doctype="Currency" :disabled="!commercialDraft||busy" /></label><label>Liste de prix <FrappeCell v-model="data.chantier.selling_price_list" doctype="Price List" :disabled="!commercialDraft||busy" /></label><label>Début prévu <input type="date" v-model="data.chantier.expected_start_date" :disabled="!commercialDraft||busy" /></label><label>Fin de fabrication prévue <input type="date" v-model="data.chantier.expected_end_date" :disabled="!commercialDraft||busy" /></label><label>Statut <span>{{stateName(data.chantier.status)}}</span></label></section>
 </div>
 <div class="body" :class="{'sections-closed':!sectionsOpen}">
 <aside class="sections"><div class="heading"><h2 v-if="sectionsOpen">Sections</h2><button :aria-expanded="sectionsOpen" aria-label="Replier ou ouvrir les sections" @click="sectionsOpen=!sectionsOpen">{{sectionsOpen?'«':'»'}}</button></div><template v-if="sectionsOpen"><template v-if="sectionRow&&commercialDraft"><div class="section-picker-heading"><span>Section de {{sectionRow.repere}}</span><button type="button" aria-label="Terminer le choix de section" @click="sectionTarget=''">×</button></div><label class="section-option" :class="{active:!sectionRow.section}"><span>Sans section</span><input type="checkbox" aria-label="Sans section pour la ligne en cours" :checked="!sectionRow.section" :disabled="busy" @change="assignSection('')" /></label><label v-for="s in data.sections" :key="s.name" class="section-option" :class="{active:sectionRow.section===s.name}" :style="{paddingLeft:(8+depth(s)*12)+'px'}"><span>{{s.section_name}}</span><input type="checkbox" :aria-label="'Affecter '+s.section_name+' à la ligne en cours'" :checked="sectionRow.section===s.name" :disabled="busy" @change="assignSection($event.target.checked?s.name:'')" /></label></template><template v-else><button :class="{active:!section}" @click="section=''">Tout le chantier <small>{{data.chantier.lines.length}}</small></button><button v-for="s in data.sections" :key="s.name" :class="{active:section===s.name}" :style="{paddingLeft:(8+depth(s)*12)+'px'}" @click="section=s.name">{{s.section_name}} <small>{{data.chantier.lines.filter(l=>l.section===s.name).length}}</small></button></template><template v-if="commercialDraft&&data.permissions?.section"><button :disabled="busy||dirty" @click="newSection">+ Section</button><details><summary>Gestion des sections</summary><button :disabled="busy||dirty" @click="importSections">Récupérer</button><button :disabled="busy||dirty" @click="generateSections">Générer avec le LLM</button><button v-if="data.permissions?.section_template" :disabled="busy||dirty" @click="saveSectionTemplate">Enregistrer comme modèle</button><button v-if="section" @click="open('Chantier Section',section)">Modifier la section</button></details></template></template></aside>
 <main class="panel macro" aria-label="Ouvrages"><div v-if="data.technical_stale" class="alert">Une nouvelle validation technique est nécessaire.</div>
 <div class="table" @keydown.enter.prevent @input="dirty=commercialDraft||dirty" @change="dirty=commercialDraft||dirty"><table><thead><tr><th><input v-if="commercialDraft" type="checkbox" aria-label="Sélectionner les ouvrages visibles" :checked="!!macroLines.length&&macroLines.every(l=>assignmentTargets.includes(l.line_id))" @input.stop @change.stop="toggleAllTargets" /></th><th></th><th>Article</th><th>Dimensions techniques / proposées (mm)</th><th>Qté</th><th>Unité</th><th>Prix unitaire</th><th>Montant</th><th>Actions</th></tr></thead><tbody><template v-for="row in macroLines" :key="row.line_id"><tr :class="{'assignment-selected':assignmentTargets.includes(row.line_id)}"><td><input v-if="commercialDraft" v-model="assignmentTargets" type="checkbox" :value="row.line_id" :disabled="busy" :aria-label="'Sélectionner '+row.repere" @change.stop @input.stop /><template v-else-if="chosen[row.line_id]"><input v-model="chosen[row.line_id].selected" type="checkbox" :disabled="!readyForQuote" /><input v-if="readyForQuote" v-model.number="chosen[row.line_id].qty" type="number" :max="row.qty-(data.quote_usage?.[row.line_id]||0)" min="0" class="qty-input" /></template></td>
 <td><button class="article-toggle" :aria-expanded="!!expandedArticles[row.line_id]" :aria-label="'Prestations de '+row.repere" @click="expandedArticles[row.line_id]=!expandedArticles[row.line_id]">{{expandedArticles[row.line_id]?'▾':'▸'}}</button></td>
 <td><FrappeCell v-model="row.designation" autocomplete label="Désignation" :disabled="!commercialDraft||busy" @update:model-value="dirty=true" /><small>{{row.repere}}</small></td>
 <td class="dimensions"><template v-for="(field,i) in ['length_mm','width_mm','thickness_mm']" :key="field"><span v-if="i"> × </span><input v-model.number="row[field]" type="number" min="0" step="any" :aria-label="field" :disabled="!commercialDraft||busy" /></template><small v-if="techLine(row.line_id)">Technique : {{techLine(row.line_id).length_mm}} × {{techLine(row.line_id).width_mm}} × {{techLine(row.line_id).thickness_mm}}</small></td>
 <td><input v-model.number="row.qty" type="number" min="1" step="1" aria-label="Quantité" :disabled="!commercialDraft||busy" class="qty-input" /></td><td><FrappeCell v-model="row.uom" doctype="UOM" :disabled="!commercialDraft||busy" @update:model-value="dirty=true" /></td>
 <td><input v-model.number="row.rate" type="number" min="0" step="any" aria-label="Prix unitaire" :disabled="!commercialDraft||busy" /></td><td>{{fmt(row.qty*row.rate)}}</td>
 <td><div class="row-actions" v-if="commercialDraft"><button :disabled="busy" title="Dupliquer" aria-label="Dupliquer l’ouvrage" @click="editMacro(row)">⧉</button><button :disabled="busy" title="Supprimer" aria-label="Supprimer l’ouvrage" @click="removeMacro(row)" class="delete-ouvrage"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7" /></svg></button><button :disabled="busy" title="Affecter une section" aria-label="Affecter une section" :aria-pressed="sectionTarget===row.line_id" @click="pickSection(row)"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M3 7V4h6l3 3h9v13H3z" /></svg></button><button :disabled="busy" title="Services / Accessoires" aria-label="Affecter des services et accessoires" @click="openExtras(row)">♧</button></div></td></tr>
