 </template></tbody></table></div>
 <footer><button v-if="commercialDraft" :disabled="busy" @click="editMacro()">+ Ajouter une ligne</button><strong>Total HT chantier : {{fmt(total)}} {{data.chantier.currency}}</strong></footer><details class="terms"><summary>Conditions commerciales</summary><textarea v-model="data.chantier.terms" :disabled="!commercialDraft||busy" @input="dirty=true"></textarea></details>
 </main>

